shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-dark: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-border: #294158;
    --crimson: #8f2822;
    --teal: #1d5c57;

    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Strict Bilingual Visibility Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.75;
  }

  /* Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(184, 93, 25, 0.24) 100%);
    color: var(--ink);
    padding: 0.08em 0.28em;
    border-bottom: 1.5px solid var(--accent);
    border-radius: 2px;
    font-weight: 600;
  }

  /* Top Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
  }

  .progress-track {
    height: 3px;
    width: 100%;
    background: transparent;
  }

  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.12s ease-out;
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.65rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .wsj-monogram {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    padding-right: 0.75rem;
    border-right: 1px solid var(--line-strong);
  }

  .section-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.28rem 0.72rem;
    border-radius: 999px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }

  .hero-kicker {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .hero-kicker .dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--accent);
  }

  .article-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.24;
    color: var(--ink);
    letter-spacing: -0.015em;
    max-width: 24ch;
    margin-bottom: 1.35rem;
  }

  :host([lang="en"]) .article-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
    max-width: 22ch;
  }

  .hero-dek {
    font-family: var(--font-sans);
    font-size: 1.08rem;
    line-height: 1.65;
    color: var(--muted);
    max-width: 760px;
    margin-bottom: 2rem;
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  .byline-author strong {
    color: var(--ink);
    font-weight: 700;
  }

  .key-dates-strip {
    display: flex;
    flex-wrap: wrap;
    gap: 1.25rem;
  }

  .key-dates-strip span strong {
    color: var(--accent);
  }

  /* Main Container */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 5rem;
  }

  /* Act 1: Asymmetric Opening Grid */
  .act-one-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(290px, 4.5fr);
    gap: 3rem;
    align-items: start;
    margin-bottom: 3.5rem;
  }

  .prose-col {
    min-width: 0;
  }

  .prose-p {
    font-size: 1.125rem;
    margin-bottom: 1.55rem;
    color: var(--body);
  }

  /* Lead paragraph styling (NO ::first-letter on Chinese) */
  .prose-p.lead-p {
    font-size: 1.28rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 600;
    padding-left: 1.15rem;
    border-left: 4px solid var(--accent);
    margin-bottom: 1.85rem;
  }

  /* Climax Quote Box for p2.s2 */
  .statement-callout {
    margin: 1.65rem 0 2rem;
    padding: 1.5rem 1.75rem;
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    position: relative;
  }

  .statement-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.5rem;
    display: block;
    font-weight: 700;
  }

  .statement-quote {
    font-size: 1.2rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.65;
  }

  /* Right Rail: Policy Metrics & Ballot Overview */
  .policy-rail {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 4px solid var(--accent);
    padding: 1.5rem;
    position: sticky;
    top: 4.5rem;
  }

  .rail-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .rail-title {
    font-family: var(--font-sans);
    font-weight: 700;
    font-size: 0.88rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--ink);
  }

  .rail-code {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--accent);
  }

  .metrics-stack {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.2rem;
    margin-bottom: 1.25rem;
  }

  .metric-card {
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 1.15rem 1.25rem;
  }

  .metric-val {
    font-family: var(--font-mono);
    font-size: 2.1rem;
    font-weight: 700;
    color: var(--accent);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }

  .metric-note {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    line-height: 1.5;
    color: var(--muted);
  }

  .rail-foot-box {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 1rem 1.15rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    line-height: 1.55;
  }

  .rail-foot-box strong {
    color: #f6ad55;
    font-family: var(--font-mono);
    display: block;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 0.25rem;
  }

  /* Bespoke Interactive/Visual Policy Architecture Section */
  .policy-anatomy-board {
    background: var(--navy-bg);
    color: #f5f2eb;
    border-radius: 3px;
    padding: 2.5rem 2rem;
    margin: 3.5rem 0;
    border: 1px solid var(--navy-border);
    box-shadow: 0 16px 36px rgba(15, 29, 43, 0.12);
  }

  .board-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    border-bottom: 1px solid var(--navy-border);
    padding-bottom: 1.25rem;
    margin-bottom: 1.75rem;
  }

  .board-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #f6ad55;
    margin-bottom: 0.4rem;
  }

  .board-title {
    font-family: var(--font-serif-cn);
    font-size: 1.5rem;
    font-weight: 700;
    color: #ffffff;
  }

  :host([lang="en"]) .board-title {
    font-family: var(--font-serif-en);
  }

  .board-sub {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    color: #b0c0d0;
    max-width: 460px;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: var(--navy-card);
    border: 1px solid var(--navy-border);
    padding: 1rem;
    margin-bottom: 1.5rem;
  }

  .mechanism-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
  }

  .mech-card {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--navy-border);
    padding: 1.15rem;
  }

  .mech-step {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: #f6ad55;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 0.4rem;
  }

  .mech-head {
    font-family: var(--font-sans);
    font-size: 0.95rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 0.45rem;
  }

  .mech-desc {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    line-height: 1.55;
    color: #cbd5e1;
  }

  /* Section Divider */
  .section-break {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 3rem 0 2rem;
  }

  .section-break-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.2rem 0.55rem;
    letter-spacing: 0.06em;
  }

  .section-break-title {
    font-family: var(--font-sans);
    font-size: 0.92rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
  }

  .section-break-line {
    flex: 1;
    height: 1px;
    background: var(--line-strong);
  }

  /* Act 2: Political Standoff & Constitutional Shield */
  .act-two-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.5fr);
    gap: 3rem;
    align-items: start;
  }

  .constitution-carveout-box {
    margin: 2rem 0;
    padding: 1.65rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 5px solid var(--teal);
  }

  .carveout-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px dashed var(--line-strong);
  }

  .carveout-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--teal);
    font-weight: 700;
  }

  .asset-comparison-strip {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.85rem;
    margin-top: 1.15rem;
    font-family: var(--font-sans);
    font-size: 0.82rem;
  }

  .asset-pill {
    padding: 0.75rem 0.9rem;
    border-radius: 2px;
  }

  .asset-pill.shielded {
    background: rgba(29, 92, 87, 0.1);
    border: 1px solid rgba(29, 92, 87, 0.35);
    color: var(--ink);
  }

  .asset-pill.exempt {
    background: rgba(184, 93, 25, 0.1);
    border: 1px solid rgba(184, 93, 25, 0.35);
    color: var(--ink);
  }

  .asset-pill strong {
    display: block;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    margin-bottom: 0.25rem;
  }

  /* Standoff Matrix Sidebar */
  .standoff-dossier {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
  }

  .dossier-title {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--ink);
    padding-bottom: 0.75rem;
    border-bottom: 2px solid var(--ink);
    margin-bottom: 1.25rem;
  }

  .camp-block {
    padding: 1rem;
    background: var(--paper);
    border: 1px solid var(--line);
    margin-bottom: 1rem;
  }

  .camp-block.camp-prop42 {
    border-left: 4px solid var(--accent);
  }

  .camp-block.camp-wealthtax {
    border-left: 4px solid var(--crimson);
  }

  .camp-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 0.45rem;
    display: block;
  }

  .camp-prop42 .camp-label { color: var(--accent); }
  .camp-wealthtax .camp-label { color: var(--crimson); }

  .camp-actors {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.4rem;
  }

  .camp-rationale {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
    line-height: 1.5;
  }

  /* Derived Pull Quote */
  .pull-quote {
    margin: 1.5rem 0 0;
    padding: 1.25rem 1.35rem;
    background: var(--paper);
    border-top: 2px solid var(--crimson);
    border-bottom: 1px solid var(--line-strong);
  }

  .pull-quote .quote-text {
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.6;
    margin-bottom: 0.6rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Final Climax Verdict Box */
  .verdict-coda {
    margin-top: 2.5rem;
    padding: 2rem;
    background: linear-gradient(180deg, var(--paper-card) 0%, var(--paper-dark) 100%);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--crimson);
  }

  .coda-label {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--crimson);
    font-weight: 700;
    margin-bottom: 0.85rem;
    display: block;
  }

  .verdict-coda .prose-p:last-child {
    margin-bottom: 0;
  }

  /* Footer */
  .ed-footer {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .act-one-grid,
    .act-two-grid,
    .mechanism-cards {
      grid-template-columns: 1fr;
    }

    .policy-rail {
      position: static;
    }
  }

  @media (max-width: 560px) {
    .masthead-inner {
      padding: 0.55rem 1rem;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .editorial-container {
      padding: 2rem 1rem 3.5rem;
    }
    .policy-anatomy-board {
      padding: 1.5rem 1rem;
    }
    .asset-comparison-strip {
      grid-template-columns: 1fr;
    }
    .verdict-coda {
      padding: 1.35rem 1.15rem;
    }
  }
